nsresult nsMsgDatabase::AddHdrToCache(
    nsIMsgDBHdr* hdr, nsMsgKey key)  // do we want key? We could get it from hdr
{
  if (m_bCacheHeaders) {
    if (!m_cachedHeaders) {
      m_cachedHeaders = new PLDHashTable(
          &gMsgDBHashTableOps, sizeof(struct MsgHdrHashElement), m_cacheSize);
    }

    if (m_cachedHeaders) {
      if (key == nsMsgKey_None) {
        hdr->GetMessageKey(&key);
      }

      if (m_cachedHeaders->EntryCount() > m_cacheSize) {
        ClearHdrCache(true);
      }

      PLDHashEntryHdr* entry =
          m_cachedHeaders->Add((void*)(uintptr_t)key, mozilla::fallible);
      if (!entry) {
        return NS_ERROR_OUT_OF_MEMORY;  // XXX out of memory
      }

      auto* element = static_cast<MsgHdrHashElement*>(entry);
      nsIMsgDBHdr* oldHdr = element->mHdr;
      if (oldHdr != hdr) {
        element->mHdr = hdr;
        element->mKey = key;
        NS_ADDREF(hdr);  // make the cache hold onto the header
        NS_IF_RELEASE(oldHdr);
      }
      return NS_OK;
    }
  }
  return NS_ERROR_FAILURE;
